import sys


def factorize(n):
    factors = []
    m = abs(n)
    if m == 0:
        return [-1]
    if m == 1:
        return [1]
    d = 2
    while d * d <= m:
        count = 0
        while m % d == 0:
            m //= d
            count += 1
        if count:
            factors.append(f"{d}^{count}")
        d += 1
    if m > 1:
        factors.append(f"{m}")
    return factors


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        factors = factorize(n)
        if n < 0:
            print(f"-{n} = -1 * {' * '.join(factors[1:])}")
        else:
            print(f"{n} = {' * '.join(factors)}")


if __name__ == "__main__":
    main()
